// Responsive image imports processed by @zerodevx/svelte-img's imagetools
// preset (srcset sources + LQIP), consumed by its <Img> component. Must live
// in an ambient (non-module) .d.ts — wildcard module declarations are ignored
// inside module files like app.d.ts.
declare module "*as=run" {
  const meta: Record<string, unknown>;
  export default meta;
}
